// ─────────────────────────────────────────────────────────────
// ASSIGN DISCORD ROLE  — runs once per user
// ─────────────────────────────────────────────────────────────
const userId    = $json.user_id;    // Discord User Snowflake ID
const rowNumber = $json.row_number; // Sheet row (for the update step)

// Pull config from the earlier Set node (available throughout the execution)
const config   = $('⚙️ Extract Config').first().json;
const guildId  = config.guildId;
const roleId   = config.roleId;
const botToken = config.botToken;

if (!guildId || !roleId || !botToken) {
  throw new Error('Config is missing guildId, roleId, or botToken. Check the Config sheet.');
}

const url = `https://discord.com/api/v10/guilds/${guildId}/members/${userId}/roles/${roleId}`;
const timestamp = new Date().toISOString();

let status   = 'done';
let errorMsg = '';

try {
  const res = await fetch(url, {
    method: 'PUT',
    headers: {
      'Authorization':      `Bot ${botToken}`,
      'Content-Type':       'application/json',
      'X-Audit-Log-Reason': 'Mass role assignment'
    }
  });

  if (res.status === 204 || res.status === 200) {
    // 204 = success, role assigned
    status = 'done';

  } else if (res.status === 429) {
    // Rate limited — back off and mark for retry
    const retryAfter = parseFloat(res.headers.get('Retry-After') ?? '1');
    await new Promise(r => setTimeout(r, retryAfter * 1000 + 500));
    status   = 'rate_limited';
    errorMsg = `Rate limited. Retry-After: ${retryAfter}s`;

  } else if (res.status === 404) {
    // User is no longer in the server — mark permanently so we skip next time
    status   = 'not_in_server';
    errorMsg = 'User not found in server (404) — they may have left.';

  } else if (res.status === 403) {
    status   = 'failed';
    errorMsg = 'Bot lacks MANAGE_ROLES permission or target role is higher than bot role (403).';

  } else {
    let body = '';
    try { body = await res.text(); } catch (_) {}
    status   = 'failed';
    errorMsg = `HTTP ${res.status}: ${body.substring(0, 200)}`;
  }

} catch (err) {
  status   = 'failed';
  errorMsg = `Network error: ${err.message}`;
}

// ─── Rate limiting: ~4 req/sec (stay comfortably under Discord limits) ───
// Only delay on successful assignments; errors already delayed above.
if (status === 'done') {
  await new Promise(r => setTimeout(r, 250));
}

return [{
  json: {
    user_id:    userId,
    row_number: rowNumber,
    status,
    timestamp,
    error:      errorMsg
  }
}];
